// th15_s7_b12: TH15 Extra BossCard6 地球「地獄に降る雨」
// Source: st07bs.ecl.txt:2096-2157 (BossCard6), 2159-2211 (BossCard6_at),
// 2213-2233 (BossCard6_at2). Rank 4 only (source !O).
// Card frame = source timerReset frame + OPENING_BUFFER; source window 4800.

const TIME_LIMIT: int = 4924;      // 120 opening + 4800 source window + 4 startup
const OPENING_BUFFER: int = 120;
const TH15_FIREBALL_BLUE: int = 784; // source etSprite type 27, color 0
const TH15_STAR_R: int = 608;        // source etSprite type 16, color 6

// BossCard6_at EX chain: 0x2 ANIM a=1 (birth position -= 4*velocity, preserved),
// 0x40 BOUNCE a=1 b=1 (wall up, one bounce), 0x8000000 LASER d=1 (delete parent).
// The async=0 LASER is gated behind the async=1 BOUNCE in the source EX chain;
// it is emitted at the top bounce point as a constant-width falling line.
xformdef BOUNCE_LIFE(delay: int) {
    offscreen_keep(8);
    bounce_arm(4, 1);
    wait(delay);
    set_life(1);
}

async sub bounce_laser() {
    while $self_y > 8fx {
        wait(1);
    }
    // source LASER: color 6, angle 90deg, speed 4, length 32->96,
    // paired width 16 -> target width 8; constant-width approximation.
    var h: int = laser(6, $self_x, $self_y, 90deg, 96fx, 8fx, 0, 9999, 0);
    if h >= 0 {
        lz_speed(h, 4fx, 96fx);
    }
}

sub emit_pair(t: int, up: int, spread_bam: int) {
    // BossCard6_at_680/1452: one shared speed draw, one shared A draw,
    // then one angle draw per shot, right shot first.
    var us: fx = ((rand(65536) - 32768) as fx) / 32768;
    var speed: fx = 1.6fx + us * 0.2fx;
    var ua: fx = ((rand(65536) - 32768) as fx) / 32768;

    // floatTime(0, %B, 150, 9, ...), mode 9 = quadratic in-out.
    var p: fx = (t as fx) / 150fx;
    var e: fx = 0fx;
    if p < 0.5fx {
        e = 2fx * p * p;
    } else {
        e = 1fx - 2fx * (1fx - p) * (1fx - p);
    }
    var b: fx = 0fx;
    if up != 0 {
        b = 180fx * e;
    } else {
        b = 180fx - 180fx * e;
    }
    var offset: fx = b + ua * 16fx;

    var u1: fx = ((rand(65536) - 32768) as fx) / 32768;
    var a1: angle = (-16384 + ((u1 * spread_bam as fx) as int)) as angle;
    var y1: fx = 448fx - 4fx * speed * sin(a1);
    var x1: fx = offset - 4fx * speed * cos(a1);
    var d1: int = (y1 / (speed * (0fx - sin(a1)))) as int;
    _ = fire(TH15_FIREBALL_BLUE, 0, x1, y1, speed, a1, BOUNCE_LIFE(d1), bounce_laser);

    var u2: fx = ((rand(65536) - 32768) as fx) / 32768;
    var a2: angle = (-16384 + ((u2 * spread_bam as fx) as int)) as angle;
    var y2: fx = 448fx - 4fx * speed * sin(a2);
    var x2: fx = 0fx - offset - 4fx * speed * cos(a2);
    var d2: int = (y2 / (speed * (0fx - sin(a2)))) as int;
    _ = fire(TH15_FIREBALL_BLUE, 0, x2, y2, speed, a2, BOUNCE_LIFE(d2), bounce_laser);
}

// BossCard6_at: wait(60), then 300-frame cycles of 20 pairs (10 x 1deg,
// then 10 x 3deg). $C=10000 is effectively endless inside this window.
sub bosscard6_at() {
    wait(60);
    var c: int = 0;
    while c < 10000 {
        c = c + 1;
        for k in 0..10 {
            emit_pair(k * 15, 0, 182);
            wait(15);
        }
        for j in 0..10 {
            emit_pair(j * 15, 1, 546);
            wait(15);
        }
    }
}

// BossCard6_at2: one aimed 32-way ring every _S(%A) frames;
// floatTime(1, %A, 3600, 9, 180, 40) (quadratic in-out).
async sub at2_pattern() {
    var t: int = 0;
    loop {
        var p: fx = (t as fx) / 3600fx;
        if p > 1fx {
            p = 1fx;
        }
        var e: fx = 0fx;
        if p < 0.5fx {
            e = 2fx * p * p;
        } else {
            e = 1fx - 2fx * (1fx - p) * (1fx - p);
        }
        var wf: fx = 180fx - 140fx * e;
        var aim: angle = aim_player();
        for i in 0..32 {
            // etAim mode 2, etAngle(0,0,0): 32-way ring aimed at the player.
            var a: angle = ((aim as int) + i * 2048) as angle;
            // source ANIM a=1: birth position -= 4 * velocity.
            _ = fire(TH15_STAR_R, 6,
                     0fx - 6fx * cos(a), 128fx - 6fx * sin(a),
                     1.5fx, a, none, none);
        }
        var w: int = wf as int;
        if w < 1 {
            w = 1;
        }
        wait(w);
        t = t + w;
    }
}

// BossCard6 entry: timerReset at source:2109; +90 wait at source:2135.
async sub boss_attack() {
    wait(OPENING_BUFFER);
    // The 120-frame buffer is synthetic; keep the boss body off during it.
    set_enemy_flag(ENEMY_NO_BODY, 0);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // movePosTime(60, 4, 0, 128)
    wait(90);
    spawn at2_pattern();
    bosscard6_at();
    loop { wait(1); }
}

async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(24fx);  // source setHitbox(48,48), circle radius 24
    set_hurtbox(20fx); // source setHurtbox(40,40), circle radius 20
    spell_begin(0, 114, boss_attack, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
